// Replays proto/testdata/collateral_vectors.json (generated by
// proto/go/attest/collateral_vectors_test.go) against collateral.ts. The two
// readers are replayed on their own as well as through the floor, because a
// reader that dated a document Go refuses would still agree on every
// fresh/stale case.

import { describe, it, expect } from 'vitest'
import * as fs from 'node:fs'
import * as path from 'node:path'
import { fileURLToPath } from 'node:url'

import {
    collateralFreshEnough,
    collateralIssuedAt,
    crlNextUpdate,
    crlThisUpdate,
    EMBEDDED_COLLATERAL_MAX_AGE_MS,
    MIN_ROOT_CA_CRL_THIS_UPDATE_MS,
} from '../src/attest/collateral.js'

type Json = Record<string, any> // eslint-disable-line @typescript-eslint/no-explicit-any
type TimeVector = { unix_sec: number; nanos: number } | null

const here = path.dirname(fileURLToPath(import.meta.url))
const v = JSON.parse(
    fs.readFileSync(path.resolve(here, '..', '..', 'testdata', 'collateral_vectors.json'), 'utf8'),
) as Json

function nanos(t: TimeVector): bigint | null {
    return t === null ? null : BigInt(t.unix_sec) * 1_000_000_000n + BigInt(t.nanos)
}

describe('collateral_vectors.json', () => {
    it('is the schema this test expects', () => {
        expect(v.version).toBe(1)
        expect(v.crl_this_update.length).toBeGreaterThan(20)
        expect(v.issued_at.length).toBeGreaterThan(10)
        expect(v.collateral_fresh.length).toBeGreaterThan(10)
    })

    it('agrees on the embedded collateral ceiling', () => {
        expect(EMBEDDED_COLLATERAL_MAX_AGE_MS).toBe(v.embedded_collateral_max_age_ms)
    })

    it('agrees on the pinned root CA CRL minimum', () => {
        expect(MIN_ROOT_CA_CRL_THIS_UPDATE_MS).toBe(v.min_root_ca_crl_this_update_unix_ms)
    })

    for (const c of v.crl_this_update) {
        it(`crlThisUpdate ${c.name}`, () => {
            expect(crlThisUpdate(c.crl_hex)).toBe(nanos(c.time))
        })
        it(`crlNextUpdate ${c.name}`, () => {
            expect(crlNextUpdate(c.crl_hex)).toBe(nanos(c.next_update))
        })
    }

    for (const c of v.issued_at) {
        it(`collateralIssuedAt ${c.name}`, () => {
            expect(collateralIssuedAt(c.doc, c.wrapper)).toBe(nanos(c.time))
        })
    }

    for (const c of v.collateral_fresh) {
        it(`collateralFreshEnough ${c.name}`, () => {
            expect(collateralFreshEnough(c.collateral, c.now_unix_ms, c.max_age_ms)).toBe(c.fresh)
        })
    }
})

// Go cannot hold a set with a missing or non-string member; a JS caller with
// an object that skipped decodeEvidenceBundle can, and must get a refusal
// rather than a throw.
describe('collateralFreshEnough on an undecoded object', () => {
    const fresh = v.collateral_fresh.find((c: Json) => c.name === 'all_now')
    for (const bad of [undefined, 5, null]) {
        it(`pck_crl ${String(bad)}`, () => {
            const coll = { ...fresh.collateral, pck_crl: bad }
            expect(collateralFreshEnough(coll, fresh.now_unix_ms, fresh.max_age_ms)).toBe(false)
        })
    }
})
